/** Wrap your UI in DSTheme, then read colors with DS.colors.blue6, DS.colors.success, … */
@Composable
fun DSTheme(darkTheme: Boolean = isSystemInDarkTheme(), content: @Composable () -> Unit) {
    CompositionLocalProvider(LocalDSColors provides if (darkTheme) DSDarkColors else DSLightColors, content = content)
}

object DS {
    val colors: DSColors
        @Composable @ReadOnlyComposable get() = LocalDSColors.current
}

