/** Raw layers from Figma. Compose elevation cannot express these exactly; use for custom drawing. */
data class DSShadowLayer(val color: Color, val offsetX: Dp, val offsetY: Dp, val blur: Dp, val spread: Dp)

object DSShadow {
    val base: List<DSShadowLayer> = listOf(
        DSShadowLayer(Color(0x05000000), 0.dp, 2.dp, 4.dp, 0.dp),
        DSShadowLayer(Color(0x05000000), 0.dp, 1.dp, 6.dp, -1.dp),
        DSShadowLayer(Color(0x08000000), 0.dp, 1.dp, 2.dp, 0.dp),
    )
    val secondary: List<DSShadowLayer> = listOf(
        DSShadowLayer(Color(0x0D000000), 0.dp, 9.dp, 28.dp, 8.dp),
        DSShadowLayer(Color(0x1F000000), 0.dp, 3.dp, 6.dp, -4.dp),
        DSShadowLayer(Color(0x14000000), 0.dp, 6.dp, 16.dp, 0.dp),
    )
    val tertiary: List<DSShadowLayer> = listOf(
        DSShadowLayer(Color(0x05000000), 0.dp, 2.dp, 4.dp, 0.dp),
        DSShadowLayer(Color(0x05000000), 0.dp, 1.dp, 6.dp, -1.dp),
        DSShadowLayer(Color(0x08000000), 0.dp, 1.dp, 2.dp, 0.dp),
    )
}
